    """Returns a matrix indicating which pairs are good according to the given threshold"""

    matrix = []
    for row in score_matrix:
        scores = []
        for entry in row:
            if entry >= threshold:
                scores.append(1)
            else:
                scores.append(0)
        matrix.append(scores)

    return matrix

